#include "common.h"
#include "test_util.hpp"

#include "gemm_config.h" // Should be generated by tune flow

namespace loopmaster
{
constexpr double alpha = 3.14;
constexpr double beta = 1.732;

using namespace unittest;

void testGencode(int m, int n, int k, int warms, int iters)
{
    int lda = m;
    int ldb = k;
    int ldc = m;
    double ops = 2.0 * m * n * k;

    double *a
        = static_cast<double *>(aligned_alloc(128, m * k * sizeof(double)));
    initRandomMatrix(m, k, a, lda);

    double *b
        = static_cast<double *>(aligned_alloc(128, n * k * sizeof(double)));
    initRandomMatrix(k, n, b, ldb);

    double *c_ref
        = static_cast<double *>(aligned_alloc(128, m * n * sizeof(double)));
    initRandomMatrix(m, n, c_ref, ldc);

    double *c_test
        = static_cast<double *>(aligned_alloc(128, m * n * sizeof(double)));
    copyMatrix(m, n, c_test, ldc, c_ref, ldc);

    if (checkGenGemm<CurrentGemmType>(
        SCHEME_NAME, m, n, k, alpha, beta, a, lda, b, ldb, c_ref, c_test, ldc))
    {
        benchAndLogGenGemm<CurrentGemmType>(
            SCHEME_NAME, m, n, k, alpha, beta,
            a, lda, b, ldb, c_test, ldc, ops, warms, iters);
    }

    free(a);
    free(b);
    free(c_ref);
    free(c_test);
}
}
// cmd args: m n k
int main(int argc, char *argv[])
{
    if (argc < 6)
    {
        printf("Usage: %s m n k warms iters\n", argv[0]);
        return 0;
    }
    int m = std::atoi(argv[1]);
    int n = std::atoi(argv[2]);
    int k = std::atoi(argv[3]);
    int warms = std::atoi(argv[4]);
    int iters = std::atoi(argv[5]);

    loopmaster::testGencode(m, n, k, warms, iters);

    return 0;
}